import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DiscountServiceTest {
    private final DiscountService service = new DiscountService();

    // GWT lives in the name; the body uses blank lines for the three phases
    @Test
    void givenPremiumCustomer_whenCalculateDiscount_thenApplies15Percent() {
        // Given: a premium customer and an order amount
        var amount = new BigDecimal("100");

        // When: the discount is calculated
        var discount = service.calculateDiscount(amount, "PREMIUM");

        // Then: 15 percent is applied
        assertEquals(new BigDecimal("15.00"), discount);
    }
}
// A Cucumber feature file expresses the same in Gherkin:
